 rel="noreferrer" target="_blank"><!--[--><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->explained each stage<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--><!--]--></a><!--[--><!--[--><!--v-if--> to make it easy to follow.<!--]--><!--]--><!--]--><!--]--></p><!--]--></div><!--]--></div></section></div><!--]--></div></section><!--]--></div></div></div><!--]--></main></div></div><div id="teleports"></div><script>window.__NUXT__={};window.__NUXT__.config={public:{ENV_NAME:"prod",PUBLIC_PATH:"https://www.evri.com",WEB_BASE:"https://www.evri.com/",PRISMIC_REPO:"ev-mercury",DEVTOOLS:false,API_BASE:"https://api.hermesworld.co.uk/",AUTH0_USERS_ENDPOINT:"https://hermes-df-prod.eu.auth0.com/userinfo",AUTH0_CLIENT_ID:"dC8K22keYtRszHe7dnmlWSve2kP7mUBF",AUTH0_DOMAIN:"hermes-df-prod.eu.auth0.com",AUTH0_LOGIN_REDIRECT:"https://www.evri.com/",AUTH0_LOGOUT_REDIRECT:"https://www.evri.com/",ASSETLINKS_PATH:"assetlinks-prod.json",APPLE_MERCHANT_DOMAIN_PATH:"apple-developer-merchantid-domain-association-PROD.txt",APPLE_APP_SITE_ASSOCIATION_PATH:"apple-app-site-association-PROD",CHATBOT_URL:"https://chat-loader.smartagent.app/loader/main.js",FEATURE_SWITCH_URL:"https://www.evri.com/feature-switches/feature-switches.json",FINDER_URL:"https://location-finder.evri.com",BASKET_API_KEY:"4GuiGkQaE92687ICJtKNRd01hc4JBKUG",BULK_API_KEY:"WtuYb1yZMIGwLJzEm0yUzhLzPGuKS632",EVRI_API_KEY:"0DExZiK9in2ihGce7cDPrnpQ4s4nIpWG",HELP_API_KEY:"IfhFrxnv1JmbNW2tBA9hnRvG1o1vnsx2",SEND_API_KEY:"fHbmtsuSHrBH5gaC6m2QF9QG3YAycmgN",TRACK_NON_ROTATING_API_KEY:"MgMPMhWhXxSp7xIoYUVnWDklTl7EXAgG",GLOBAL_CSS_URI:"https://resources.hermescloud.co.uk/global/",ROUTER_BASE:"/",ACCOUNT_ENDPOINT:"https://api.hermesworld.co.uk/enterprise-user-account-api/v1/",BUSINESS_ACCOUNT_ENDPOINT:"https://api.hermesworld.co.uk/business-account-enquiry-api/v1/",CLIENTS_JSON:"https://www.evri.com/clients/clients.js",CUSTOMER_ORDER_ENDPOINT:"https://api.hermesworld.co.uk/customer-order-api/v1/",RETAILERS_ENDPOINT: